(async function(){
  let settings;try{settings=await NMData.getSettings()}catch{return}const ads=settings.ads||{};
  function safeUrl(url){try{const parsed=new URL(url);return['http:','https:'].includes(parsed.protocol)?parsed.href:'#'}catch{return'#'}}
  function rail(side,data){if(!data?.active)return;const size=data.size==='160x600'?'160x600':'160x300';if(data.mode==='code'&&data.code){const box=document.createElement('aside'),frame=document.createElement('iframe');box.className=`side-ad side-ad-${side} network-ad`;box.dataset.size=size;box.setAttribute('aria-label',data.label||`Iklan ${side}`);box.innerHTML=`<span>${String(data.label||'IKLAN').replace(/[<>]/g,'')}</span>`;frame.title=data.label||`Iklan ${side}`;frame.sandbox='allow-scripts allow-popups allow-popups-to-escape-sandbox allow-forms';frame.referrerPolicy='no-referrer-when-downgrade';frame.srcdoc=`<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>html,body{margin:0;min-height:100%;background:transparent;display:flex;align-items:flex-start;justify-content:center;overflow:hidden}img,iframe{max-width:100%}</style></head><body>${data.code}</body></html>`;box.append(frame);box.insertAdjacentHTML('beforeend','<small>IKLAN</small>');document.body.appendChild(box);return}const link=document.createElement('a');link.className=`side-ad side-ad-${side}`;link.dataset.size=size;link.href=safeUrl(data.url);link.target='_blank';link.rel='noopener noreferrer sponsored';link.setAttribute('aria-label',data.label||`Iklan ${side}`);link.innerHTML=data.image?`<span>${String(data.label||'SPONSOR').replace(/[<>]/g,'')}</span><img src="${String(data.image).replace(/["<>]/g,'')}" alt="${String(data.label||'Iklan').replace(/["<>]/g,'')}"><small>IKLAN</small>`:`<span>${String(data.label||'RUANG IKLAN').replace(/[<>]/g,'')}</span><b>Pasang iklan<br>di sini</b><small>IKLAN</small>`;document.body.appendChild(link)}
  rail('left',ads.left);rail('right',ads.right);
})();
